/** Havok helpers. Return owned disposable handles; collision categories are caller-configurable. */
export function staticCollider(runtime,mesh,{friction=.8,restitution=.08,category=1,mask=0xffffffff,shape=runtime.B.PhysicsShapeType.BOX}={}){const{B,scene}=runtime,a=new B.PhysicsAggregate(mesh,shape,{mass:0,friction,restitution},scene);a.shape.filterMembershipMask=category;a.shape.filterCollideMask=mask;return a;}
export function controlledCapsule(runtime,{name='controller',height=1.8,radius=.35,category=4,mask=8}={}){const{B,scene}=runtime,mesh=B.MeshBuilder.CreateCapsule(name,{height,radius,tessellation:6},scene);mesh.isVisible=false;const aggregate=new B.PhysicsAggregate(mesh,B.PhysicsShapeType.CAPSULE,{mass:0},scene);aggregate.body.setMotionType(B.PhysicsMotionType.ANIMATED);aggregate.body.disablePreStep=false;aggregate.shape.filterMembershipMask=category;aggregate.shape.filterCollideMask=mask;return{mesh,aggregate,move(x,y,z){mesh.position.set(x,y,z);mesh.computeWorldMatrix(true);},dispose(){aggregate.dispose();mesh.dispose();}};}
export function dynamicBox(runtime,mesh,{mass=1,friction=.6,restitution=.15,category=8,mask=1|4|8}={}){const{B,scene}=runtime,a=new B.PhysicsAggregate(mesh,B.PhysicsShapeType.BOX,{mass,friction,restitution},scene);a.shape.filterMembershipMask=category;a.shape.filterCollideMask=mask;return a;}
